--[[ Train3D - railway platform scene (Crayon Engine). Assets generated by tools/generate_train.py
     Click = mouse look, WASD walk, SHIFT run, arrows look, ESC release, H help ]]
local A="assets/"
local VW,VH=320,240
local gfx; local M,TX={}, {}; local font
local cam={x=-3.6,y=2.55,z=2.0,yaw=24,pitch=-6}
local captured,skipDelta,showHelp=false,false,true
local function clamp(v,a,b) return math.max(a,math.min(b,v)) end

function crayon.config(t)
    t.identity="Train3D"
    -- 320x240 virtual resolution; window is 2x that so scaling stays pixel-crisp.
    t.window={title="Train3D",width=320,height=240,virtualWidth=VW,virtualHeight=VH,resizable=true,vsync=true,scaling="aspect"}
    t.modules={physics3D=false,physics2D=false,physics4D=false,audio=false,mesh3D=true,input=true}
    t.graphics={clearColor={0.8,0.82,0.8,1}}
end

function crayon.init()
    gfx=crayon.graphics
    for _,n in ipairs({"ground","grass","ballast","platform","sky","props","tank","wagon","train"}) do M[n]=gfx.loadModel(A.."models/"..n..".obj") end
    for _,n in ipairs({"ground","grass","ballast","platform","sky","palette","tank"}) do TX[n]=gfx.loadTexture(A.."textures/"..n..".png") end
    font=gfx.loadFont("res/IBMPlexSans-Bold.ttf",16)
    gfx.setRetroEffects({affine=0,fog={startDist=40,endDist=170,color={0.82,0.84,0.82}}})
end

function crayon.update(dt)
    dt=math.min(dt,0.05)
    local k,ms=crayon.key,crayon.mouse
    local lx,ly,mx,mz=0,0,0,0
    if not captured and ms.isPressed(1) then captured=true; skipDelta=true; pcall(function() ms.setRelativeMode(true); ms.setVisible(false) end) end
    if captured then
        if k.isPressed("escape") then captured=false; pcall(function() ms.setRelativeMode(false); ms.setVisible(true) end)
        elseif skipDelta then skipDelta=false
        else local dx,dy=ms.getDelta(); lx,ly=dx*0.1,dy*0.1 end
    end
    if k.isDown("left") then lx=lx-90*dt end
    if k.isDown("right") then lx=lx+90*dt end
    if k.isDown("up") then ly=ly-60*dt end
    if k.isDown("down") then ly=ly+60*dt end
    if k.isPressed("h") then showHelp=not showHelp end
    cam.yaw=cam.yaw+lx; cam.pitch=clamp(cam.pitch-ly,-85,85)
    if k.isDown("w") then mz=mz+1 end
    if k.isDown("s") then mz=mz-1 end
    if k.isDown("d") then mx=mx+1 end
    if k.isDown("a") then mx=mx-1 end
    local len=math.sqrt(mx*mx+mz*mz); if len>1 then mx,mz=mx/len,mz/len end
    local sp=(k.isDown("lshift","rshift") and 8 or 3)
    local yaw=math.rad(cam.yaw)
    local fx,fz,rx,rz=math.sin(yaw),-math.cos(yaw),math.cos(yaw),math.sin(yaw)
    cam.x=clamp(cam.x+(fx*mz+rx*mx)*sp*dt,-8.5,-2.7)   -- stay on the platform
    cam.z=clamp(cam.z+(fz*mz+rz*mx)*sp*dt,-180,5)
end

function crayon.draw()
    gfx.clear(0.8,0.82,0.8)
    local yaw,pit=math.rad(cam.yaw),math.rad(cam.pitch)
    gfx.setCamera3D({position={cam.x,cam.y,cam.z},
        target={cam.x+math.cos(pit)*math.sin(yaw),cam.y+math.sin(pit),cam.z-math.cos(pit)*math.cos(yaw)},
        up={0,1,0},fov=70,near=0.1,far=200})
    gfx.setColor(1,1,1,1)

    -- Sky dome: culling off so it renders from inside regardless of model winding.
    gfx.setCullFace(false)
    gfx.setShadingMode("unlit")
    gfx.drawModel(M.sky,cam.x,cam.y,cam.z,0,0,0,1,1,1,TX.sky)

    -- Everything else: back-face culling halves triangle throughput.
    gfx.setCullFace("back")
    gfx.setShadingMode("gouraud")
    -- overcast: soft top light, high ambient
    gfx.setLight(0.2,-1,0.3, 0.55,0.55,0.53, 0.55,0.56,0.56)
    local function d(m,t) gfx.drawModel(M[m],0,0,0,0,0,0,1,1,1,TX[t]) end
    d("ground","ground"); d("grass","grass"); d("ballast","ballast"); d("platform","platform")
    d("props","palette"); d("tank","tank"); d("wagon","palette"); d("train","palette")

    gfx.setColor(1,1,1,0.8); gfx.drawCircle("fill",VW/2,VH/2,1.5,8)
    gfx.setFont(font)
    if showHelp then
        gfx.setColor(1,1,1,0.8)
        gfx.drawText("Click: look  |  WASD: move  |  Shift: run", 10, VH-26, 1)
        gfx.drawText("Arrows: look  |  H: toggle help",           10, VH-14, 1)
    end
end